import React, { useEffect, useRef } from 'react';

export default function PropertyDetailsModal({ show, onClose, property, onScheduleVisit }) {
  const mapRef = useRef(null);
  const mapInstance = useRef(null);

  useEffect(() => {
    if (show && property?.location?.lat && property?.location?.lng) {
      const initMap = () => {
        if (window.L && mapRef.current && !mapInstance.current) {
          const lat = Number(property.location.lat);
          const lng = Number(property.location.lng);
          
          const map = window.L.map(mapRef.current).setView([lat, lng], 15);
          
          window.L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            attribution: '&copy; OpenStreetMap contributors'
          }).addTo(map);

          window.L.marker([lat, lng]).addTo(map);
          mapInstance.current = map;
        }
      };

      if (!window.L) {
        // تحميل Leaflet إذا لم يكن موجوداً
        if (!document.getElementById('leaflet-css')) {
            const link = document.createElement('link');
            link.id = 'leaflet-css';
            link.rel = 'stylesheet';
            link.href = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
            document.head.appendChild(link);
        }
        const script = document.createElement('script');
        script.src = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
        script.async = true;
        script.onload = initMap;
        document.body.appendChild(script);
      } else {
        setTimeout(initMap, 200); // تأخير بسيط لضمان عرض المودال
      }
    }

    return () => {
        if (mapInstance.current) {
            mapInstance.current.remove();
            mapInstance.current = null;
        }
    };
  }, [show, property]);

  if (!property) return null;

  // Mock data for "Neighborhood Insights"
  const insights = [
    { label: 'الهدوء والراحة', score: 90, icon: '🍃' },
    { label: 'القرب من الخدمات', score: 85, icon: '🛒' },
    { label: 'المناطق الخضراء', score: 70, icon: '🌳' },
    { label: 'سهولة المواصلات', score: 80, icon: '🚌' },
  ];

  return (
    <div className={`modal fade ${show ? 'show d-block' : ''}`} tabIndex="-1" style={{ background: 'rgba(0,0,0,0.6)', zIndex: 1060 }}>
      <div className="modal-dialog modal-xl modal-dialog-centered modal-dialog-scrollable">
        <div className="modal-content border-0 shadow-lg overflow-hidden zoom-in">
          <div className="modal-header border-0 bg-primary text-white">
            <h5 className="modal-title">✨ تفاصيل العقار الملهمة</h5>
            <button type="button" className="btn-close btn-close-white" onClick={onClose}></button>
          </div>
          <div className="modal-body p-0">
            {/* Hero Image */}
            <div style={{ height: '300px', overflow: 'hidden', position: 'relative' }}>
              <img src={property.imageUrl} alt={property.type} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
              <div className="position-absolute bottom-0 start-0 w-100 p-3" style={{ background: 'linear-gradient(to top, rgba(0,0,0,0.8), transparent)' }}>
                <h2 className="text-white mb-0">{property.type} في {property.location?.city}</h2>
                <p className="text-white-50 mb-0">{property.location?.neighborhood}</p>
              </div>
            </div>

            <div className="row g-0">
              <div className="col-lg-8 p-4">
                <h4 className="mb-3 text-primary">وصف العقار</h4>
                <p className="lead text-muted" style={{ whiteSpace: 'pre-line' }}>{property.description}</p>
                
                <div className="row text-center my-4">
                  <div className="col-3">
                    <div className="p-3 border rounded bg-light">
                      <div className="fs-2">📏</div>
                      <small>{property.area} م²</small>
                    </div>
                  </div>
                  <div className="col-3">
                    <div className="p-3 border rounded bg-light">
                      <div className="fs-2">🛋️</div>
                      <small>{property.rooms} غرف</small>
                    </div>
                  </div>
                  <div className="col-3">
                    <div className="p-3 border rounded bg-light">
                      <div className="fs-2">🛁</div>
                      <small>{property.bathrooms} حمام</small>
                    </div>
                  </div>
                  <div className="col-3">
                    <div className="p-3 border rounded bg-light">
                      <div className="fs-2">💰</div>
                      <small>{property.price?.toLocaleString()} ج</small>
                    </div>
                  </div>
                </div>

                <h5 className="mb-3">🌟 نظرة على الحي (تقريبي)</h5>
                <div className="row g-3">
                  {insights.map((insight, idx) => (
                    <div key={idx} className="col-md-6">
                      <div className="d-flex align-items-center mb-1">
                        <span className="me-2 fs-5">{insight.icon}</span>
                        <span className="fw-bold">{insight.label}</span>
                        <span className="ms-auto text-primary fw-bold">{insight.score}%</span>
                      </div>
                      <div className="progress" style={{ height: '8px' }}>
                        <div className="progress-bar bg-info" role="progressbar" style={{ width: `${insight.score}%` }}></div>
                      </div>
                    </div>
                  ))}
                </div>

                {property.location?.lat && property.location?.lng && (
                  <div className="mt-4">
                    <h5 className="mb-3">📍 الموقع على الخريطة</h5>
                    <div ref={mapRef} style={{ width: '100%', height: '300px', borderRadius: '15px' }} className="shadow-sm border"></div>
                  </div>
                )}
              </div>

              <div className="col-lg-4 bg-light p-4 border-start">
                <div className="card border-0 shadow-sm mb-4">
                  <div className="card-body text-center">
                    <img src={property.ownerPhoto || 'https://cdn.pixabay.com/photo/2015/10/05/22/37/blank-profile-picture-973460_960_720.png'} className="rounded-circle mb-3 shadow-sm" style={{width: 80, height: 80, objectFit: 'cover'}} alt="Owner" />
                    <h5>{property.ownerName}</h5>
                    <p className="text-muted small">مالك العقار</p>
                    <div className="d-grid gap-2">
                      <a href={`tel:${property.ownerPhone}`} className="btn btn-outline-primary">📞 اتصال</a>
                      <a href={`https://wa.me/${property.ownerPhone}`} target="_blank" rel="noreferrer" className="btn btn-success">📱 واتساب</a>
                    </div>
                  </div>
                </div>

                <div className="d-grid">
                  <button className="btn btn-primary btn-lg mb-2 shadow-sm" onClick={() => { onClose(); onScheduleVisit(property); }}>📅 حجز موعد معاينة</button>
                  <button className="btn btn-outline-secondary" onClick={onClose}>إغلاق</button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
